      id: "acc_" + Date.now(),
      methodId: matchedOpt.id,
      bankType: matchedOpt.name,
      logo: matchedOpt.logo,
      accNumber: num,
      accHolder: holder,
      accType: "Personal",
      createdAt: new Date().toISOString()
